const DEST_PREFIXES = ['/inflyteappfiltered', '/apps/musicsorted'];
let sortedNames = new Set();
try {
 sortedNames = new Set(
 $('List Sorted Files (Bulk)').all()
 .filter(i => {
 const p = (i.json.path_lower || i.json.path_display || '').toLowerCase();
 return DEST_PREFIXES.some(prefix => p.startsWith(prefix));
 })
 .map(i => (i.json.name || '').toLowerCase())
 );
} catch (e) {
 sortedNames = new Set();
}
return $input.all().map(item => {
 const name = (item.json.name || '').toLowerCase();
 return { json: { ...item.json, matches: sortedNames.has(name) ? [{ name }] : [] } };
});

