// Resolve final genre from Python detection and AI assist
const item = $input.first().json;
const pyGenre = item.py_genre || 'Unknown';
const pySubgenre = item.py_subgenre || 'Unknown';
const pyConf = item.py_confidence || 0;
const aiGenre = item.ai_genre || '';
const aiSubgenre = item.ai_subgenre || '';
const aiConf = item.ai_confidence || 0;

let finalGenre, finalSubgenre, finalConf, finalSource;

// Decision logic: prefer higher confidence, AI wins ties if it was used
if (aiConf > pyConf && aiGenre) {
 finalGenre = aiGenre;
 finalSubgenre = aiSubgenre || aiGenre;
 finalConf = aiConf;
 finalSource = 'openai';
} else if (pyGenre && pyGenre !== 'Unknown') {
 finalGenre = pyGenre;
 finalSubgenre = pySubgenre;
 finalConf = pyConf;
 finalSource = item.used_ai ? 'python_preferred' : 'python';
} else if (aiGenre) {
 finalGenre = aiGenre;
 finalSubgenre = aiSubgenre || aiGenre;
 finalConf = aiConf;
 finalSource = 'openai_fallback';
} else {
 finalGenre = 'Unsorted';
 finalSubgenre = 'Unknown';
 finalConf = 0;
 finalSource = 'none';
}

// Determine confidence tier for folder routing
let confTier = 'low';
if (finalConf >= 0.7) confTier = 'high';
else if (finalConf >= 0.4) confTier = 'medium';

// Build target folder path
let targetFolder;
if (confTier === 'high') {
 targetFolder = `/Apps/MusicSorted/${finalGenre}/${finalSubgenre}`;
} else if (confTier === 'medium') {
 targetFolder = `/Apps/MusicSorted/${finalGenre}/_Needs Review`;
} else {
 targetFolder = `/Apps/MusicSorted/_Manual Review`;
}

return [{
 json: { ...($input.first().json), 
 ...item,
 final_genre: finalGenre,
 final_subgenre: finalSubgenre,
 final_confidence: finalConf,
 final_source: finalSource,
 confidence_tier: confTier,
 target_folder: targetFolder
 }
}];

const stdout = $input.first().json.stdout || '';
const lines = stdout.trim().split('\n').filter(l => l.trim());

const records = [];
for (const line of lines) {
 try {
 const obj = JSON.parse(line);
 if (obj.genre) records.push(obj);
 } catch(e) {}
}

// Aggregate stats
const genreCounts = {};
const sourceCounts = {};
const tierCounts = { high: 0, medium: 0, low: 0 };
let totalBPM = 0, bpmCount = 0;

for (const r of records) {
 genreCounts[r.genre] = (genreCounts[r.genre] || 0) + 1;
 sourceCounts[r.source] = (sourceCounts[r.source] || 0) + 1;
 tierCounts[r.tier] = (tierCounts[r.tier] || 0) + 1;
 if (r.bpm > 0) { totalBPM += r.bpm; bpmCount++; }
}

const avgBPM = bpmCount > 0 ? Math.round(totalBPM / bpmCount) : 0;
const genreLabels = Object.keys(genreCounts);
const genreData = genreLabels.map(k => genreCounts[k]);

