const items = $input.all();
const entries = (items[0] && items[0].json && items[0].json.entries) || [];
const imageExts = ['.jpg', '.jpeg', '.png', '.gif', '.bmp'];
const onlyImagesOrEmpty = entries.every(e => {
 const name = (e.name || '').toLowerCase();
 return imageExts.some(ext => name.endsWith(ext));
});
return [{
 json: { shouldDeleteFolder: onlyImagesOrEmpty, remainingCount: entries.length, remainingNames: entries.map(e => e.name) }
}];

